CREATE COLUMN TABLE "TEST_AP"."GDP2" ("AbsEntry" INTEGER CS_INT NOT NULL , "LineNum" SMALLINT CS_INT NOT NULL , "NatObjType" NVARCHAR(20) NOT NULL , "NatObjArr" INTEGER CS_INT NOT NULL , "NatObjKey1" NVARCHAR(20) NOT NULL , "NatObjKey2" NVARCHAR(20) NOT NULL , "Result" INTEGER CS_INT, "ErrorStr" NVARCHAR(254), PRIMARY KEY ("AbsEntry", "LineNum")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "GDP2_NATOBJ_KEY" ON "TEST_AP"."GDP2" ( "AbsEntry" ASC, "NatObjType" ASC, "NatObjArr" ASC, "NatObjKey1" ASC, "NatObjKey2" ASC )